@Test
public void testReadThroughputLatency() throws Exception {
    final AtomicBoolean threwException = new AtomicBoolean(false);
    Thread t = new Thread() {

        public void run() {
            try {
                BenchReadThroughputLatency.main(new String[] { "--zookeeper", zkUtil.getZooKeeperConnectString(), "--listen", "10" });
            } catch (Throwable t) {
                LOG.error("Error reading", t);
                threwException.set(true);
            }
        }
    };
    t.start();
    Thread.sleep(10000);
    byte[] data = new byte[1024];
    Arrays.fill(data, (byte) 'x');
    long lastLedgerId = 0;
    Assert.assertTrue("Thread should be running", t.isAlive());
    for (int i = 0; i < 10; i++) {
        BookKeeper bk = new BookKeeper(zkUtil.getZooKeeperConnectString());
        LedgerHandle lh = bk.createLedger(BookKeeper.DigestType.CRC32, "benchPasswd".getBytes());
        lastLedgerId = lh.getId();
        try {
            for (int j = 0; j < 100; j++) {
                lh.addEntry(data);
            }
        } finally {
            lh.close();
            bk.close();
        }
    }
    for (int i = 0; i < 60; i++) {
        if (!t.isAlive()) {
            break;
        }
        Thread.sleep(100);
    }
    Assert.assertFalse("Thread should be finished", t.isAlive());
    BenchReadThroughputLatency.main(new String[] { "--zookeeper", zkUtil.getZooKeeperConnectString(), "--ledger", String.valueOf(lastLedgerId) });
}

@Test
public void simple() throws Exception {
    BlockingQueue<Integer> queue = new BatchedArrayBlockingQueue<>(4);
    assertEquals(null, queue.poll());
    assertEquals(4, queue.remainingCapacity());
    try {
        queue.element();
        fail("Should have thrown exception");
    } catch (NoSuchElementException e) {
        // Expected
    }
    try {
        queue.iterator();
        fail("Should have thrown exception");
    } catch (UnsupportedOperationException e) {
        // Expected
    }
    // Test index rollover
    for (int i = 0; i < 100; i++) {
        queue.add(i);
        assertEquals(i, queue.take().intValue());
    }
    queue.offer(1);
    queue.offer(2);
    queue.offer(3);
    queue.offer(4);
    assertEquals(4, queue.size());
    List<Integer> list = new ArrayList<>();
    queue.drainTo(list, 3);
    assertEquals(1, queue.size());
    assertEquals(Lists.newArrayList(1, 2, 3), list);
    assertEquals(4, queue.peek().intValue());
    assertEquals(4, queue.element().intValue());
    assertEquals(4, queue.remove().intValue());
    try {
        queue.remove();
        fail("Should have thrown exception");
    } catch (NoSuchElementException e) {
        // Expected
    }
}

@Test
public void blockingTake() throws Exception {
    BlockingQueue<Integer> queue = new GrowableMpScArrayConsumerBlockingQueue<>();
    CountDownLatch latch = new CountDownLatch(1);
    new Thread(() -> {
        try {
            int expected = 0;
            for (int i = 0; i < 100; i++) {
                int n = queue.take();
                assertEquals(expected++, n);
            }
            latch.countDown();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }).start();
    int n = 0;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            queue.put(n);
            ++n;
        }
        // Wait until all the entries are consumed
        while (!queue.isEmpty()) {
            Thread.sleep(1);
        }
    }
    latch.await();
}

@Test
public void blockWhenFull() throws Exception {
    BlockingQueue<Integer> queue = new BatchedArrayBlockingQueue<>(4);
    assertEquals(null, queue.poll());
    assertTrue(queue.offer(1));
    assertTrue(queue.offer(2));
    assertTrue(queue.offer(3));
    assertTrue(queue.offer(4));
    assertFalse(queue.offer(5));
    assertEquals(4, queue.size());
    CountDownLatch latch = new CountDownLatch(1);
    new Thread(() -> {
        try {
            queue.put(5);
            latch.countDown();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }).start();
    Thread.sleep(100);
    assertEquals(1, latch.getCount());
    assertEquals(1, (int) queue.poll());
    assertTrue(latch.await(1, TimeUnit.SECONDS));
    assertEquals(4, queue.size());
    queue.clear();
    assertEquals(0, queue.size());
    assertTrue(queue.offer(1, 1, TimeUnit.SECONDS));
    assertTrue(queue.offer(2, 1, TimeUnit.SECONDS));
    assertTrue(queue.offer(3, 1, TimeUnit.SECONDS));
    assertEquals(3, queue.size());
    List<Integer> list = new ArrayList<>();
    queue.drainTo(list);
    assertEquals(0, queue.size());
    assertEquals(Lists.newArrayList(1, 2, 3), list);
}

