@Test
public void testWriteAndRecovery() throws Exception {
    // this WriteHandle will not be closed
    WriteHandle lh = result(bkc.newCreateLedgerOp().withEnsembleSize(1).withWriteQuorumSize(1).withAckQuorumSize(1).withWriteFlags(WriteFlag.DEFERRED_SYNC).withDigestType(DigestType.CRC32C).withPassword(new byte[0]).execute());
    int n = 10;
    long ledgerId = lh.getId();
    for (int i = 0; i < n; i++) {
        lh.append(("entry-" + i).getBytes(UTF_8));
    }
    try (ReadHandle readLh = result(bkc.newOpenLedgerOp().withLedgerId(ledgerId).withRecovery(true).withPassword(new byte[0]).execute())) {
        try (LedgerEntries entries = readLh.read(0, n - 1)) {
            for (int i = 0; i < n; i++) {
                org.apache.bookkeeper.client.api.LedgerEntry entry = entries.getEntry(i);
                assertEquals("entry-" + i, new String(entry.getEntryBytes()));
            }
        }
    }
}

