/**
 * Check bookie status should be able to persist on disk and retrieve when restart the bookie.
 */
@Test(timeout = 10000)
public void testPersistBookieStatus() throws Exception {
    // enable persistent bookie status
    File tmpDir = tmpDirs.createNew("bookie", "test");
    final ServerConfiguration conf = TestBKConfiguration.newServerConfiguration();
    conf.setJournalDirName(tmpDir.getPath()).setLedgerDirNames(new String[] { tmpDir.getPath() }).setReadOnlyModeEnabled(true).setPersistBookieStatusEnabled(true).setMetadataServiceUri(metadataServiceUri);
    BookieServer bookieServer = new BookieServer(conf, new TestBookieImpl(conf), NullStatsLogger.INSTANCE, UnpooledByteBufAllocator.DEFAULT, new MockUncleanShutdownDetection());
    bookieServer.start();
    Bookie bookie = bookieServer.getBookie();
    assertFalse(bookie.isReadOnly());
    // transition to readonly mode, bookie status should be persisted in ledger disks
    bookie.getStateManager().transitionToReadOnlyMode().get();
    assertTrue(bookie.isReadOnly());
    // restart bookie should start in read only mode
    bookieServer.shutdown();
    bookieServer = new BookieServer(conf, new TestBookieImpl(conf), NullStatsLogger.INSTANCE, UnpooledByteBufAllocator.DEFAULT, new MockUncleanShutdownDetection());
    bookieServer.start();
    bookie = bookieServer.getBookie();
    assertTrue(bookie.isReadOnly());
    // transition to writable mode
    bookie.getStateManager().transitionToWritableMode().get();
    // restart bookie should start in writable mode
    bookieServer.shutdown();
    bookieServer = new BookieServer(conf, new TestBookieImpl(conf), NullStatsLogger.INSTANCE, UnpooledByteBufAllocator.DEFAULT, new MockUncleanShutdownDetection());
    bookieServer.start();
    bookie = bookieServer.getBookie();
    assertFalse(bookie.isReadOnly());
    bookieServer.shutdown();
}

