@Test
public void testRunDontRunThenRunAgain() throws Exception {
    AtomicBoolean needsFullCheck = new AtomicBoolean(true);
    Semaphore semaphore = new Semaphore(1);
    // increment the count, can only be released by a check
    semaphore.acquire();
    MockDataIntegrityCheck check = new MockDataIntegrityCheck() {

        @Override
        public boolean needsFullCheck() {
            return needsFullCheck.getAndSet(false);
        }

        @Override
        public CompletableFuture<Void> runFullCheck() {
            semaphore.release();
            return super.runFullCheck();
        }
    };
    DataIntegrityService service = newLowIntervalService(check);
    try {
        service.start();
        Assert.assertTrue("Check should have run", semaphore.tryAcquire(10, TimeUnit.SECONDS));
        Assert.assertFalse("Check shouldn't run again", semaphore.tryAcquire(100, TimeUnit.MILLISECONDS));
        needsFullCheck.set(true);
        Assert.assertTrue("Check should run again", semaphore.tryAcquire(10, TimeUnit.SECONDS));
    } finally {
        service.stop();
    }
}

