@Test
public void testPartialRead() throws Exception {
    File ledgerDir = tmpDirs.createNew("partialRead", "logs");
    int entrySize = Buffer.ALIGNMENT * 4;
    NativeIOImpl nativeIO = new NativeIOImpl() {

        @Override
        public long pread(int fd, long buf, long size, long offset) throws NativeIOException {
            long read = super.pread(fd, buf, size, offset);
            // force only less than a buffer read
            return Math.min(read, Buffer.ALIGNMENT);
        }

        @Override
        public int fallocate(int fd, int mode, long offset, long len) throws NativeIOException {
            // don't preallocate
            return 0;
        }
    };
    try (BufferPool buffers = new BufferPool(new NativeIOImpl(), ByteBufAllocator.DEFAULT, Buffer.ALIGNMENT * 10, 8);
