@Test
public void testCommandLine() throws Exception {
    PrintStream origerr = System.err;
    PrintStream origout = System.out;
    File output = IOUtils.createTempFileAndDeleteOnExit("bookie", "stdout");
    File erroutput = IOUtils.createTempFileAndDeleteOnExit("bookie", "stderr");
    System.setOut(new PrintStream(output));
    System.setErr(new PrintStream(erroutput));
    try {
        FileSystemUpgrade.main(new String[] { "-h" });
        try {
            // test without conf
            FileSystemUpgrade.main(new String[] { "-u" });
            fail("Should have failed");
        } catch (IllegalArgumentException iae) {
            assertTrue("Wrong exception " + iae.getMessage(), iae.getMessage().contains("without configuration"));
        }
        File f = IOUtils.createTempFileAndDeleteOnExit("bookie", "tmpconf");
        try {
            // test without upgrade op
            FileSystemUpgrade.main(new String[] { "--conf", f.getPath() });
            fail("Should have failed");
        } catch (IllegalArgumentException iae) {
            assertTrue("Wrong exception " + iae.getMessage(), iae.getMessage().contains("Must specify -upgrade"));
        }
    } finally {
        System.setOut(origout);
        System.setErr(origerr);
    }
}

@Test
public void testFSUGetAllDirectories() throws Exception {
    ServerConfiguration conf = TestBKConfiguration.newServerConfiguration();
    final File journalDir = tmpDirs.createNew("bookie", "journal");
    final File ledgerDir1 = tmpDirs.createNew("bookie", "ledger");
    final File ledgerDir2 = tmpDirs.createNew("bookie", "ledger");
    // test1
    conf.setJournalDirName(journalDir.getPath()).setLedgerDirNames(new String[] { ledgerDir1.getPath(), ledgerDir2.getPath() }).setIndexDirName(new String[] { ledgerDir1.getPath(), ledgerDir2.getPath() });
    List<File> allDirectories = FileSystemUpgrade.getAllDirectories(conf);
    assertEquals(3, allDirectories.size());
    // test2
    conf.setJournalDirName(journalDir.getPath()).setLedgerDirNames(new String[] { ledgerDir1.getPath(), ledgerDir2.getPath() }).setIndexDirName(new String[] { ledgerDir2.getPath(), ledgerDir1.getPath() });
    allDirectories = FileSystemUpgrade.getAllDirectories(conf);
    assertEquals(3, allDirectories.size());
    final File indexDir1 = tmpDirs.createNew("bookie", "index");
    final File indexDir2 = tmpDirs.createNew("bookie", "index");
    // test3
    conf.setJournalDirName(journalDir.getPath()).setLedgerDirNames(new String[] { ledgerDir1.getPath(), ledgerDir2.getPath() }).setIndexDirName(new String[] { indexDir1.getPath(), indexDir2.getPath() });
    allDirectories = FileSystemUpgrade.getAllDirectories(conf);
    assertEquals(5, allDirectories.size());
    // test4
    conf.setJournalDirName(journalDir.getPath()).setLedgerDirNames(new String[] { ledgerDir1.getPath(), ledgerDir2.getPath() }).setIndexDirName(new String[] { indexDir2.getPath(), indexDir1.getPath() });
    allDirectories = FileSystemUpgrade.getAllDirectories(conf);
    assertEquals(5, allDirectories.size());
}

@Test
public void testGetMessage() throws Exception {
    Field[] fields = BKException.Code.class.getFields();
    int count = 0;
    for (Field f : fields) {
        if (f.getType() == Integer.TYPE && !f.getName().equals("UNINITIALIZED")) {
            int code = f.getInt(null);
            String msg = BKException.getMessage(code);
            if (code == UnexpectedConditionException) {
                assertEquals("Unexpected condition", msg);
            } else {
                assertNotEquals("failure on code " + f.getName(), "Unexpected condition", msg);
            }
            count++;
        }
    }
    // assert that we found at least 1 code other than UnexpectedConditionException
    assertTrue(count > 2);
}

@Test
public void testWriteHandle() throws Exception {
    try (WriteHandle writer = result(newCreateLedgerOp().withAckQuorumSize(1).withWriteQuorumSize(2).withEnsembleSize(3).withPassword(password).execute())) {
