    adminConf.setMetadataServiceUri(zkUtil.getMetadataServiceUri());
    setMetastoreImplClass(adminConf);
    bka = new BookKeeperAdmin(adminConf);
    bka.recoverBookieData(bookieSrc);
    bka.close();
    lh = bkc.openLedgerNoRecovery(ledgerId, digestCorrect, passwdCorrect);
    assertTrue(verifyFullyReplicated(lh, 100), "Should be back to fully replication");
    lh.close();
}

@Test
public void testRecoveryClosedLedger() throws BKException, IOException, InterruptedException {
    // test the v2 protocol when using IO thread to handle the request
    ClientConfiguration conf = new ClientConfiguration();
    conf.setMetadataServiceUri(zkUtil.getMetadataServiceUri());
    conf.setUseV2WireProtocol(true);
    AtomicInteger finalRc = new AtomicInteger(Integer.MAX_VALUE);
    CountDownLatch latch = new CountDownLatch(1);
    try (BookKeeper bkc = new BookKeeper(conf)) {
        bkc.asyncCreateLedger(1, 1, BookKeeper.DigestType.CRC32, "".getBytes(), new AsyncCallback.CreateCallback() {

            @Override
            public void createComplete(int rc, LedgerHandle lh, Object ctx) {
                lh.asyncAddEntry("hello".getBytes(), new AsyncCallback.AddCallback() {

                    @Override
                    public void addComplete(int rc, LedgerHandle lh, long entryId, Object ctx) {
                        if (rc == BKException.Code.OK) {
                            bkc.asyncOpenLedger(lh.ledgerId, BookKeeper.DigestType.CRC32, "".getBytes(), new AsyncCallback.OpenCallback() {

                                @Override
                                public void openComplete(int rc, LedgerHandle lh, Object ctx) {
                                    finalRc.set(rc);
                                    latch.countDown();
                                }
                            }, null);
                        }
                    }
                }, null);
            }
        }, null);
        latch.await();
    }
    assertEquals(finalRc.get(), org.apache.bookkeeper.client.api.BKException.Code.OK);
}

