@Test
public void testInitNewCluster() throws Exception {
    ServerConfiguration newConfig = new ServerConfiguration(baseConf);
    String ledgersRootPath = "/testledgers";
    newConfig.setMetadataServiceUri(newMetadataServiceUri(ledgersRootPath));
    Assert.assertTrue("New cluster should be initialized successfully", BookKeeperAdmin.initNewCluster(newConfig));
    Assert.assertTrue("Cluster rootpath should have been created successfully " + ledgersRootPath, (zkc.exists(ledgersRootPath, false) != null));
    String availableBookiesPath = ZKMetadataDriverBase.resolveZkLedgersRootPath(newConfig) + "/" + AVAILABLE_NODE;
    Assert.assertTrue("AvailableBookiesPath should have been created successfully " + availableBookiesPath, (zkc.exists(availableBookiesPath, false) != null));
    String readonlyBookiesPath = availableBookiesPath + "/" + READONLY;
    Assert.assertTrue("ReadonlyBookiesPath should have been created successfully " + readonlyBookiesPath, (zkc.exists(readonlyBookiesPath, false) != null));
    String instanceIdPath = ZKMetadataDriverBase.resolveZkLedgersRootPath(newConfig) + "/" + BookKeeperConstants.INSTANCEID;
    Assert.assertTrue("InstanceId node should have been created successfully" + instanceIdPath, (zkc.exists(instanceIdPath, false) != null));
    String ledgersLayout = ledgersRootPath + "/" + BookKeeperConstants.LAYOUT_ZNODE;
    Assert.assertTrue("Layout node should have been created successfully" + ledgersLayout, (zkc.exists(ledgersLayout, false) != null));
    /**
     * create znodes simulating existence of Bookies in the cluster
     */
    int numOfBookies = 3;
