    Assert.assertFalse("Cluster should'nt be nuked since incorrect instanceid is provided", BookKeeperAdmin.nukeExistingCluster(newConfig, ledgersRootPath, "incorrectinstanceid", false));
    Assert.assertFalse("Cluster should'nt be nuked since bookies are still registered", BookKeeperAdmin.nukeExistingCluster(newConfig, ledgersRootPath, readInstanceId, false));
    /*
         * delete all rw bookies registration
         */
    for (int i = 0; i < bookiesRegPaths.size(); i++) {
        zkc.delete(bookiesRegPaths.get(i), -1);
    }
    Assert.assertFalse("Cluster should'nt be nuked since ro bookie is still registered", BookKeeperAdmin.nukeExistingCluster(newConfig, ledgersRootPath, readInstanceId, false));
