    conf.setMetadataServiceUri(zkUtil.getMetadataServiceUri());
    for (int i = 0; i < 10; i++) {
        final BookKeeper client = new BookKeeper(conf);
        final CountDownLatch l = new CountDownLatch(1);
        final AtomicBoolean success = new AtomicBoolean(false);
        Thread t = new Thread() {

            public void run() {
                try {
