            // assert local LAC does not change after reads
            assertTrue((rlh.getLastAddConfirmed() == (numOfEntries - 2)), "Expected LAC of rlh: " + (numOfEntries - 2) + " actual LAC of rlh: " + rlh.getLastAddConfirmed());
            // read all entries within the LastAddConfirmed..numOfEntries - 1 range with readUnconfirmedEntries
            assertEquals(numOfEntries - rlh.getLastAddConfirmed(), Collections.list(rlh.readUnconfirmedEntries(rlh.getLastAddConfirmed(), numOfEntries - 1)).size());
            // assert local LAC does not change after reads
            assertTrue((rlh.getLastAddConfirmed() == (numOfEntries - 2)), "Expected LAC of rlh: " + (numOfEntries - 2) + " actual LAC of rlh: " + rlh.getLastAddConfirmed());
            try {
