public void testConcurrentOpen() throws Exception {
    ClientConfiguration conf = new ClientConfiguration();
    conf.setMetadataServiceUri(zkUtil.getMetadataServiceUri()).setNumChannelsPerBookie(16).setUseV2WireProtocol(true).setZkTimeout(20000).setAddEntryTimeout(30).setReadEntryTimeout(30).setSpeculativeReadTimeout(0).setThrottleValue(0).setLedgerManagerFactoryClassName(HierarchicalLedgerManagerFactory.class.getName());
    BookKeeper bkc = new BookKeeper(conf);
    for (int j = 0; j < 10; j++) {
        LedgerHandle lh = bkc.createLedger(DigestType.CRC32, "testPasswd".getBytes());
        lh.addEntry("foobar".getBytes());
        long ledgerId = lh.getId();
        final long finalLedgerId = ledgerId;
        ExecutorService executor = Executors.newFixedThreadPool(10);
        List<Future<?>> futures = new ArrayList<>();
        CountDownLatch latch = new CountDownLatch(1);
        for (int i = 0; i < 5; i++) {
            final CompletableFuture<LedgerHandle> future = new CompletableFuture<>();
            executor.submit(() -> {
                latch.await();
                bkc.asyncOpenLedger(finalLedgerId, DigestType.CRC32, "testPasswd".getBytes(), (rc, handle, ctx) -> {
                    if (rc != BKException.Code.OK) {
                        future.completeExceptionally(BKException.create(rc));
                    } else {
                        future.complete(handle);
                    }
                }, null);
                return future;
            });
            futures.add(future);
        }
        latch.countDown();
        for (Future<?> f : futures) {
            try {
                f.get(10, TimeUnit.SECONDS);
            } catch (ExecutionException ee) {
                // also fine, recovery can currently fail because of metadata conflicts.
                // We should fix this at some point by making the metadata immutable,
                // and restarting the entire operation
                Assert.assertEquals(ee.getCause().getClass(), BKException.BKLedgerRecoveryException.class);
            }
        }
    }
    bkc.close();
}

