        // block the write trying to do the first close
        if (!closeInProgress.isDone() && metadata.isClosed()) {
            closeInProgress.complete(null);
            return blockClose;
        } else {
            return FutureUtils.value(null);
        }
    });
    CompletableFuture<?> closeFuture = lh.closeAsync();
