    /* close with different length. can happen in cases where there's a write outstanding */
    ClientUtil.transformMetadata(clientCtx, 10L, (metadata) -> LedgerMetadataBuilder.from(metadata).withClosedState().withLastEntryId(lac + 1).withLength(length + 100).build());
