@Test
public void testCloseWhileAddInProgress() throws Exception {
    MockClientContext clientCtx = MockClientContext.create();
    Versioned<LedgerMetadata> md = ClientUtil.setupLedger(clientCtx, 10L, LedgerMetadataBuilder.create().withEnsembleSize(3).withWriteQuorumSize(3).withAckQuorumSize(2).newEnsembleEntry(0L, Lists.newArrayList(b1, b2, b3)));
