@Test
public void testDoubleCloseOnHandle() throws Exception {
    long ledgerId = 123L;
    MockClientContext clientCtx = MockClientContext.create();
    Versioned<LedgerMetadata> md = ClientUtil.setupLedger(clientCtx, ledgerId, LedgerMetadataBuilder.create().withEnsembleSize(3).withWriteQuorumSize(3).withAckQuorumSize(3).newEnsembleEntry(0L, Lists.newArrayList(b1, b2, b3)));
    CompletableFuture<Void> metadataPromise = new CompletableFuture<>();
    CompletableFuture<Void> clientPromise = new CompletableFuture<>();
    LedgerHandle writer = new LedgerHandle(clientCtx, ledgerId, md, BookKeeper.DigestType.CRC32C, ClientUtil.PASSWD, WriteFlag.NONE);
    long eid1 = writer.append("entry1".getBytes());
    log.info("block writes from completing on bookies and metadata");
    clientCtx.getMockBookieClient().setPostWriteHook((bookie, lid, eid) -> clientPromise);
    clientCtx.getMockLedgerManager().setPreWriteHook((lid, metadata) -> metadataPromise);
    log.info("try to add another entry, it will block");
    writer.appendAsync("entry2".getBytes());
    log.info("attempt one close, should block forever");
    CompletableFuture<Void> firstClose = writer.closeAsync();
    log.info("attempt second close, should not finish before first one");
    CompletableFuture<Void> secondClose = writer.closeAsync();
    // give it a chance to complete, the request jumps around threads
    Thread.sleep(500);
    Assert.assertFalse(firstClose.isDone());
    Assert.assertFalse(secondClose.isDone());
}

@Test
public void testLedgerCloseWithConsistentLength() throws Exception {
    ClientConfiguration conf = new ClientConfiguration();
    conf.setMetadataServiceUri(zkUtil.getMetadataServiceUri());
    conf.setReadTimeout(1);
    BookKeeper bkc = new BookKeeper(conf);
    LedgerHandle lh = bkc.createLedger(6, 3, DigestType.CRC32, new byte[] {});
    final CountDownLatch latch = new CountDownLatch(1);
    stopBKCluster();
    final AtomicInteger i = new AtomicInteger(0xdeadbeef);
    AsyncCallback.AddCallback cb = new AsyncCallback.AddCallback() {

        @Override
        public void addComplete(int rc, LedgerHandle lh, long entryId, Object ctx) {
            i.set(rc);
            latch.countDown();
        }
    };
    lh.asyncAddEntry("Test Entry".getBytes(), cb, null);
    latch.await();
    assertEquals(i.get(), BKException.Code.NotEnoughBookiesException);
    assertEquals(0, lh.getLength());
    assertEquals(LedgerHandle.INVALID_ENTRY_ID, lh.getLastAddConfirmed());
    startBKCluster(zkUtil.getMetadataServiceUri());
    LedgerHandle newLh = bkc.openLedger(lh.getId(), DigestType.CRC32, new byte[] {});
    assertEquals(0, newLh.getLength());
    assertEquals(LedgerHandle.INVALID_ENTRY_ID, newLh.getLastAddConfirmed());
}

