    responseCode = readLACFromQuorum(readLh, BKException.Code.BookieHandleNotAvailableException, BKException.Code.OK);
    assertEquals(responseCode, BKException.Code.OK);
    // Test 1: bookie response: OK, NO_SUCH_LEDGER_EXISTS
