}

@Test
public void testExecuteAfterCancelled() {
    AtomicInteger rcHolder = new AtomicInteger(-0xdead);
    PendingAddOp op = PendingAddOp.create(lh, mockClientContext, lh.getCurrentEnsemble(), payload, WriteFlag.NONE, (rc, handle, entryId, qwcLatency, ctx) -> {
        rcHolder.set(rc);
    }, null);
    assertSame(lh, op.lh);
    // cancel the op.
    op.submitCallback(Code.NotEnoughBookiesException);
    // if a op is cancelled, it is not recycled until it has been run.
    assertSame(lh, op.lh);
