public void testShouldNotGetTheFragmentIfThereIsNoMissedEntry() throws Exception {
    LedgerHandle lh = bkc.createLedger(3, 2, BookKeeper.DigestType.CRC32, TEST_LEDGER_PASSWORD);
    lh.addEntry(TEST_LEDGER_ENTRY_DATA);
    // Entry should have added in first 2 Bookies.
    // Kill the 3rd BK from ensemble.
    List<BookieId> firstEnsemble = lh.getLedgerMetadata().getAllEnsembles().get(0L);
    BookieId lastBookieFromEnsemble = firstEnsemble.get(2);
    LOG.info("Killing " + lastBookieFromEnsemble + " from ensemble=" + firstEnsemble);
    killBookie(lastBookieFromEnsemble);
    startNewBookie();
    LOG.info("Ensembles after first entry :" + lh.getLedgerMetadata().getAllEnsembles());
    // Adding one more entry. Here enseble should be reformed.
    lh.addEntry(TEST_LEDGER_ENTRY_DATA);
    LOG.info("Ensembles after second entry :" + lh.getLedgerMetadata().getAllEnsembles());
    Set<LedgerFragment> result = getUnderReplicatedFragments(lh);
    assertNotNull("Result shouldn't be null", result);
    for (LedgerFragment r : result) {
        LOG.info("unreplicated fragment: {}", r);
    }
    assertEquals("Empty fragment should be considered missing", 1, result.size());
}

