@Test
public void testSplitLedgerFragmentState() throws Exception {
    int lastEntryId = 10;
    int rereplicationEntryBatchSize = 10;
    List<BookieId> ensemble = new ArrayList<BookieId>();
    ensemble.add(BookieId.parse("bookie0:3181"));
    ensemble.add(BookieId.parse("bookie1:3181"));
    ensemble.add(BookieId.parse("bookie2:3181"));
    ensemble.add(BookieId.parse("bookie3:3181"));
    ensemble.add(BookieId.parse("bookie4:3181"));
    ensemble.add(BookieId.parse("bookie5:3181"));
    ensemble.add(BookieId.parse("bookie6:3181"));
    LedgerMetadataBuilder builder = LedgerMetadataBuilder.create();
    builder.withId(124L).withEnsembleSize(7).withWriteQuorumSize(3).withAckQuorumSize(2).withDigestType(TEST_DIGEST_TYPE.toApiDigestType()).withPassword(TEST_PSSWD).newEnsembleEntry(0, ensemble).withLastEntryId(lastEntryId).withLength(512).withClosedState();
    LedgerMetadata met = builder.build();
    LedgerHandle lh = new LedgerHandle(bkc.getClientCtx(), 100L, new Versioned<>(met, new LongVersion(0L)), TEST_DIGEST_TYPE, TEST_PSSWD, EnumSet.noneOf(WriteFlag.class));
    /*
         * create LedgerFragment from the ledger ensemble for the bookies with
         * indexes 1 and 5.
         */
    Set<Integer> bookieIndexes = new HashSet<>();
    bookieIndexes.add(1);
    bookieIndexes.add(5);
    LedgerFragment lfrag = new LedgerFragment(lh, 0, 10, bookieIndexes);
    /*
         * Since this ledger contains 11 entries (lastEntryId is 10), when it is
         * split into subFragments of size 10 it will be split into 2. In the
         * first subfragment, firstEntryID (and firstStoredEntryId) will be 0.
         * lastKnownEntryID will be 9 but lastStoredEntryId will be 8. Because
         * entry 9 will not be stored in both of the nodes and entry 8 is the
         * last entry that is stored in either one of the node.
         *
         * In the second sub-fragment firstEntryID, firstStoredEntryId,
         * lastKnownEntryID and lastStoredEntryId should be 10.
         */
    Set<LedgerFragment> partitionedFragments = LedgerFragmentReplicator.splitIntoSubFragments(lh, lfrag, rereplicationEntryBatchSize);
    assertEquals("Number of sub-fragments", 2, partitionedFragments.size());
    for (LedgerFragment partitionedFragment : partitionedFragments) {
        if (partitionedFragment.getFirstEntryId() == 0) {
            validateEntryIds(partitionedFragment, 0, 0, 9, 8);
        } else {
            validateEntryIds(partitionedFragment, 10, 10, 10, 10);
        }
    }
}

@Test
public void testRecoverLedgerFragmentEntrySendRightRequestWithFlag() throws Exception {
    CountDownLatch latch = new CountDownLatch(1);
    BookieClientImpl bookieClient = Mockito.mock(BookieClientImpl.class);
    doAnswer(invocationOnMock -> {
        ByteBuf toSend = invocationOnMock.getArgument(4);
        BookieProtoEncoding.RequestEnDeCoderPreV3 deCoderPreV3 = new BookieProtoEncoding.RequestEnDeCoderPreV3(null);
        toSend.readerIndex(4);
        BookieProtocol.ParsedAddRequest request = (BookieProtocol.ParsedAddRequest) deCoderPreV3.decode(toSend);
        Field flagField = request.getClass().getSuperclass().getDeclaredField("flags");
        flagField.setAccessible(true);
        short flag = flagField.getShort(request);
        assertEquals(flag, BookieProtocol.FLAG_RECOVERY_ADD);
        latch.countDown();
        return null;
    }).when(bookieClient).addEntry(any(), anyLong(), any(), anyLong(), any(), any(), any(), anyInt(), anyBoolean(), any());
    BookKeeper bkc = Mockito.mock(BookKeeper.class);
    when(bkc.getBookieClient()).thenReturn(bookieClient);
    LedgerHandle lh = Mockito.mock(LedgerHandle.class);
    DummyDigestManager ds = new DummyDigestManager(1L, true, ByteBufAllocator.DEFAULT);
    when(lh.getDigestManager()).thenReturn(ds);
    when(lh.getLedgerKey()).thenReturn(DigestManager.generateMasterKey("".getBytes()));
    ByteBuf data = Unpooled.wrappedBuffer(new byte[1024]);
    LedgerEntry entry = new LedgerEntry(LedgerEntryImpl.create(1L, 1L, data.readableBytes(), data));
    List<LedgerEntry> list = new LinkedList<>();
    list.add(entry);
    Enumeration<LedgerEntry> entries = IteratorUtils.asEnumeration(list.iterator());
    doAnswer(invocation -> {
        org.apache.bookkeeper.client.AsyncCallback.ReadCallback rc = invocation.getArgument(2, org.apache.bookkeeper.client.AsyncCallback.ReadCallback.class);
        rc.readComplete(0, lh, entries, null);
