    addrs.add(addr1.toBookieId());
    addrs.add(addr2.toBookieId());
    addrs.add(addr3.toBookieId());
    addrs.add(addr4.toBookieId());
    repp.onClusterChanged(addrs, new HashSet<BookieId>());
    try {
        int ensembleSize = 3;
        int writeQuorumSize = 2;
        int acqQuorumSize = 2;
        EnsemblePlacementPolicy.PlacementResult<List<BookieId>> ensembleResponse = repp.newEnsemble(ensembleSize, writeQuorumSize, acqQuorumSize, null, new HashSet<>());
        List<BookieId> ensemble = ensembleResponse.getResult();
        PlacementPolicyAdherence isEnsembleAdheringToPlacementPolicy = ensembleResponse.getAdheringToPolicy();
        int numCovered = getNumCoveredWriteQuorums(ensemble, writeQuorumSize, conf.getMinNumRacksPerWriteQuorum(), repp.bookieAddressResolver);
        assertTrue(numCovered >= 1 && numCovered < 3);
        assertEquals(PlacementPolicyAdherence.FAIL, isEnsembleAdheringToPlacementPolicy);
        ensembleSize = 4;
        EnsemblePlacementPolicy.PlacementResult<List<BookieId>> ensembleResponse2 = repp.newEnsemble(ensembleSize, writeQuorumSize, acqQuorumSize, null, new HashSet<>());
        List<BookieId> ensemble2 = ensembleResponse2.getResult();
