@Test
public void testWeightedPlacementAndReplaceBookieWithoutEnoughBookiesInSameRack() throws Exception {
    BookieSocketAddress addr0 = new BookieSocketAddress("126.0.0.1", 3181);
    BookieSocketAddress addr1 = new BookieSocketAddress("127.0.0.1", 3181);
    BookieSocketAddress addr2 = new BookieSocketAddress("127.0.0.2", 3181);
    BookieSocketAddress addr3 = new BookieSocketAddress("127.0.0.3", 3181);
    BookieSocketAddress addr4 = new BookieSocketAddress("127.0.0.4", 3181);
    // update dns mapping
    StaticDNSResolver.reset();
    StaticDNSResolver.addNodeToRack(addr0.getSocketAddress().getAddress().getHostAddress(), NetworkTopology.DEFAULT_REGION + "/r0");
    StaticDNSResolver.addNodeToRack(addr1.getSocketAddress().getAddress().getHostAddress(), NetworkTopology.DEFAULT_REGION_AND_RACK);
    StaticDNSResolver.addNodeToRack(addr2.getSocketAddress().getAddress().getHostAddress(), NetworkTopology.DEFAULT_REGION + "/r2");
    StaticDNSResolver.addNodeToRack(addr3.getSocketAddress().getAddress().getHostAddress(), NetworkTopology.DEFAULT_REGION + "/r3");
    StaticDNSResolver.addNodeToRack(addr4.getSocketAddress().getAddress().getHostAddress(), NetworkTopology.DEFAULT_REGION + "/r4");
    // Update cluster
    Set<BookieId> addrs = new HashSet<BookieId>();
    addrs.add(addr0.toBookieId());
    addrs.add(addr1.toBookieId());
    addrs.add(addr2.toBookieId());
    addrs.add(addr3.toBookieId());
    addrs.add(addr4.toBookieId());
    int multiple = 10, maxMultiple = 4;
    conf.setDiskWeightBasedPlacementEnabled(true);
    conf.setBookieMaxWeightMultipleForWeightBasedPlacement(maxMultiple);
    repp.initialize(conf, Optional.<DNSToSwitchMapping>empty(), timer, DISABLE_ALL, NullStatsLogger.INSTANCE, BookieSocketAddress.LEGACY_BOOKIEID_RESOLVER);
    repp.withDefaultRack(NetworkTopology.DEFAULT_REGION_AND_RACK);
    repp.onClusterChanged(addrs, new HashSet<BookieId>());
    Map<BookieId, BookieInfo> bookieInfoMap = new HashMap<BookieId, BookieInfo>();
    bookieInfoMap.put(addr0.toBookieId(), new BookieInfo(50L, 50L));
    bookieInfoMap.put(addr1.toBookieId(), new BookieInfo(100L, 100L));
    bookieInfoMap.put(addr2.toBookieId(), new BookieInfo(100L, 100L));
    bookieInfoMap.put(addr3.toBookieId(), new BookieInfo(200L, 200L));
    bookieInfoMap.put(addr4.toBookieId(), new BookieInfo(multiple * 50L, multiple * 50L));
    repp.updateBookieInfo(bookieInfoMap);
    Map<BookieId, Long> selectionCounts = new HashMap<BookieId, Long>();
    selectionCounts.put(addr0.toBookieId(), 0L);
    selectionCounts.put(addr1.toBookieId(), 0L);
    selectionCounts.put(addr2.toBookieId(), 0L);
    selectionCounts.put(addr3.toBookieId(), 0L);
    selectionCounts.put(addr4.toBookieId(), 0L);
    int numTries = 50000;
    EnsemblePlacementPolicy.PlacementResult<BookieId> replaceBookieResponse;
    BookieId replacedBookie;
    PlacementPolicyAdherence isEnsembleAdheringToPlacementPolicy;
    for (int i = 0; i < numTries; i++) {
        // addr2 is on /r2 and this is the only one on this rack. So the replacement
        // will come from other racks. However, the weight should be honored in such
        // selections as well
        replaceBookieResponse = repp.replaceBookie(1, 1, 1, null, new ArrayList<>(), addr2.toBookieId(), new HashSet<>());
        replacedBookie = replaceBookieResponse.getResult();
        isEnsembleAdheringToPlacementPolicy = replaceBookieResponse.getAdheringToPolicy();
        assertTrue(addr0.toBookieId().equals(replacedBookie) || addr1.toBookieId().equals(replacedBookie) || addr3.toBookieId().equals(replacedBookie) || addr4.toBookieId().equals(replacedBookie));
        assertEquals(PlacementPolicyAdherence.MEETS_STRICT, isEnsembleAdheringToPlacementPolicy);
        selectionCounts.put(replacedBookie, selectionCounts.get(replacedBookie) + 1);
    }
    /*
         * Even though addr2 has to be replaced, but being excluded bookie weight is not excluded in the choose list.
         * All the bookies weight are - 50, 100, 100, 200, 500 (10*50)
         * So the median calculated by WeightedRandomSelection is 100
         */
    double medianWeight = 100;
    double medianSelectionCounts = (double) (medianWeight / bookieInfoMap.get(addr1.toBookieId()).getWeight()) * selectionCounts.get(addr1.toBookieId());
    double observedMultiple1 = ((double) selectionCounts.get(addr4.toBookieId()) / (double) medianSelectionCounts);
    double observedMultiple2 = ((double) selectionCounts.get(addr4.toBookieId()) / (double) selectionCounts.get(addr3.toBookieId()));
    LOG.info("oM1 " + observedMultiple1 + " oM2 " + observedMultiple2);
    assertTrue("Weights not being honored expected " + maxMultiple + " observed " + observedMultiple1, Math.abs(observedMultiple1 - maxMultiple) < 1);
    // expected multiple for addr3
    double expected = (medianWeight * maxMultiple) / bookieInfoMap.get(addr3.toBookieId()).getWeight();
    assertTrue("Weights not being honored expected " + expected + " observed " + observedMultiple2, Math.abs(observedMultiple2 - expected) < 1);
}

