    assertFalse("since ackQuorumSize is 3, it should return false", zepp.areAckedBookiesAdheringToPlacementPolicy(ackedBookies, 10, 3));
    assertTrue("since ackQuorumSize is 2 and bookies are from minNumZonesPerWriteQuorum it should return true", zepp.areAckedBookiesAdheringToPlacementPolicy(ackedBookies, 10, 2));
    zepp.uninitalize();
    newConf = (ClientConfiguration) this.conf.clone();
    newConf.setDesiredNumZonesPerWriteQuorum(4);
    newConf.setMinNumZonesPerWriteQuorum(4);
