        assertEquals("PlacementPolicyAdherence", PlacementPolicyAdherence.MEETS_STRICT, ensembleResponse.getAdheringToPolicy());
    }
    // we could still use addr4 for urgent allocation if it is just bookie
    // flapping
    EnsemblePlacementPolicy.PlacementResult<List<BookieId>> ensembleResponse = zepp.newEnsemble(4, 4, 2, null, new HashSet<BookieId>());
    List<BookieId> ensemble = ensembleResponse.getResult();
    assertTrue(ensemble.contains(addr4.toBookieId()));
    assertEquals("PlacementPolicyAdherence", PlacementPolicyAdherence.MEETS_STRICT, ensembleResponse.getAdheringToPolicy());
}

