    LedgerMetadata lm = LedgerMetadataBuilder.create().withId(13L).withEnsembleSize(3).withWriteQuorumSize(2).withAckQuorumSize(1).withPassword("foobar".getBytes(UTF_8)).withDigestType(DigestType.CRC32C).newEnsembleEntry(0L, Lists.newArrayList(new BookieSocketAddress("192.0.2.1", 1234).toBookieId(), new BookieSocketAddress("192.0.2.2", 1234).toBookieId(), new BookieSocketAddress("192.0.2.3", 1234).toBookieId())).withCreationTime(123456L).storingCreationTime(true).build();
