    initMeta = LedgerMetadataBuilder.create().withId(3L).withEnsembleSize(ensembleSize).withWriteQuorumSize(writeQuorumSize).withAckQuorumSize(ackQuorumSize).newEnsembleEntry(0L, bookieAddresses.subList(0, 4)).withDigestType(DigestType.DUMMY).withPassword(new byte[0]).build();
