    lm.createLedgerMetadata(4L, initMeta).get();
    ServerConfiguration servConf = new ServerConfiguration(confByIndex(0));
    servConf.setMinNumRacksPerWriteQuorum(minNumRacksPerWriteQuorumConfValue);
    setServerConfigPropertiesForRackPlacement(servConf);
    MutableObject<Auditor> auditorRef = new MutableObject<Auditor>();
    try {
        TestStatsLogger statsLogger = startAuditorAndWaitForPlacementPolicyCheck(servConf, auditorRef);
        Gauge<? extends Number> ledgersNotAdheringToPlacementPolicyGuage = statsLogger.getGauge(ReplicationStats.NUM_LEDGERS_NOT_ADHERING_TO_PLACEMENT_POLICY);
        Gauge<? extends Number> ledgersSoftlyAdheringToPlacementPolicyGuage = statsLogger.getGauge(ReplicationStats.NUM_LEDGERS_SOFTLY_ADHERING_TO_PLACEMENT_POLICY);
        /*
             * since all of the bookies are in different racks, there shouldn't be any ledger not adhering
             * to placement policy.
             */
        assertEquals("NUM_LEDGERS_NOT_ADHERING_TO_PLACEMENT_POLICY guage value", 0, ledgersNotAdheringToPlacementPolicyGuage.getSample());
        /*
             * since all of the bookies are in different racks, there shouldn't be any ledger softly adhering
             * to placement policy.
             */
        assertEquals("NUM_LEDGERS_SOFTLY_ADHERING_TO_PLACEMENT_POLICY guage value", 0, ledgersSoftlyAdheringToPlacementPolicyGuage.getSample());
    } finally {
        Auditor auditor = auditorRef.getValue();
        if (auditor != null) {
            auditor.close();
        }
        regManager.close();
    }
}

