@Test
public void testReadWriteAsyncLength() throws IOException {
    SyncObj sync = new SyncObj();
    try {
        // Create a ledger
        lh = bkc.createLedger(digestType, ledgerPassword);
        // bkc.initMessageDigest("SHA1");
        ledgerId = lh.getId();
        LOG.info("Ledger ID: " + lh.getId());
