        // close ledger
        lh.close();
        // *** WRITING PART COMPLETE // READ PART BEGINS ***
        // open ledger
        lh = bkc.openLedger(ledgerId, digestType, ledgerPassword);
        assertTrue("Ledger length after opening: " + lh.getLength(), lh.getLength() == length);
        lh.close();
