@Test
public void testTLSChannelCounters() throws Exception {
    ClientConfiguration tlsClientConf = new ClientConfiguration(baseClientConf).setNumChannelsPerBookie(1);
    ClientConfiguration nonTlsClientConf = new ClientConfiguration(baseClientConf).setNumChannelsPerBookie(1).setTLSProviderFactoryClass(null);
    TestStatsProvider tlsStatsProvider = new TestStatsProvider();
    TestStatsProvider nonTlsStatsProvider = new TestStatsProvider();
    BookKeeperTestClient tlsClient = new BookKeeperTestClient(tlsClientConf, tlsStatsProvider);
    BookKeeperTestClient nonTlsClient = new BookKeeperTestClient(nonTlsClientConf, nonTlsStatsProvider);
    // IO load from clients
    testClient(tlsClient, numBookies);
    testClient(nonTlsClient, numBookies);
    // verify stats
    for (int i = 0; i < numBookies; i++) {
        BookieServer bookie = serverByIndex(i);
        StringBuilder nameBuilder = new StringBuilder(BookKeeperClientStats.CHANNEL_SCOPE).append(".").append("bookie_").append(TestUtils.buildStatsCounterPathFromBookieID(bookie.getBookieId())).append(".");
        // check stats on TLS enabled client
        assertEquals("Mismatch TLS channel count", 1, tlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.ACTIVE_TLS_CHANNEL_COUNTER).get().longValue());
        assertEquals("TLS handshake failure unexpected", 0, tlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.FAILED_TLS_HANDSHAKE_COUNTER).get().longValue());
        assertEquals("Mismatch non-TLS channel count", 0, tlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.ACTIVE_NON_TLS_CHANNEL_COUNTER).get().longValue());
        assertEquals("Connection failures unexpected", 0, tlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.FAILED_CONNECTION_COUNTER).get().longValue());
        // check stats on non-TLS enabled client
        assertEquals("Mismatch TLS channel count", 0, nonTlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.ACTIVE_TLS_CHANNEL_COUNTER).get().longValue());
        assertEquals("TLS handshake failure unexpected", 0, nonTlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.FAILED_TLS_HANDSHAKE_COUNTER).get().longValue());
        assertEquals("Mismatch non-TLS channel count", 1, nonTlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.ACTIVE_NON_TLS_CHANNEL_COUNTER).get().longValue());
        assertEquals("Connection failures unexpected", 0, nonTlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.FAILED_CONNECTION_COUNTER).get().longValue());
        bookie.shutdown();
        assertEquals("Mismatch TLS channel count", 0, tlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.ACTIVE_TLS_CHANNEL_COUNTER).get().longValue());
        assertEquals("Mismatch non-TLS channel count", 0, nonTlsClient.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.ACTIVE_NON_TLS_CHANNEL_COUNTER).get().longValue());
    }
}

/**
 * Verify handshake failure due to missing entry in trust store.
 */
@Test
public void testHandshakeFailure() throws Exception {
    ClientConfiguration clientConf = new ClientConfiguration(baseClientConf).setNumChannelsPerBookie(1);
    // restart a bookie with wrong trust store
    int restartBookieIdx = 0;
    ServerConfiguration badBookieConf = confByIndex(restartBookieIdx);
    switch(serverTrustStoreFormat) {
        case PEM:
            badBookieConf.setTLSTrustStore(getResourcePath("server-cert.pem"));
            break;
        case JKS:
            badBookieConf.setTLSTrustStore(getResourcePath("server-key.jks")).setTLSTrustStorePasswordPath(getResourcePath("keyStoreServerPassword.txt"));
            break;
        case PKCS12:
            badBookieConf.setTLSTrustStore(getResourcePath("server-key.p12")).setTLSTrustStorePasswordPath(getResourcePath("keyStoreServerPassword.txt"));
            break;
        default:
            throw new Exception("Unrecognized trust store format: " + serverTrustStoreFormat);
    }
    killBookie(restartBookieIdx);
    LOG.info("Sleeping for 1s before restarting bookie with bad cert");
    Thread.sleep(1000);
    BookieServer bookie = startAndAddBookie(badBookieConf).getServer();
    // Create ledger and write entries
    TestStatsProvider testStatsProvider = new TestStatsProvider();
    BookKeeperTestClient client = new BookKeeperTestClient(clientConf, testStatsProvider);
    byte[] passwd = "testPassword".getBytes();
    int numEntries = 2;
    byte[] testEntry = "testEntry".getBytes();
    // should fail to write entries whey WQ == AQ == 3
    try (LedgerHandle lh = client.createLedger(numBookies, numBookies, numBookies, DigestType.CRC32, passwd)) {
        for (int i = 0; i <= numEntries; i++) {
            lh.addEntry(testEntry);
        }
        fail("Should have failed with not enough bookies to write");
    } catch (BKException.BKNotEnoughBookiesException bke) {
        // expected
    }
    // check failed handshake counter
    StringBuilder nameBuilder = new StringBuilder(BookKeeperClientStats.CHANNEL_SCOPE).append(".").append("bookie_").append(TestUtils.buildStatsCounterPathFromBookieID(bookie.getBookieId())).append(".");
    assertEquals("TLS handshake failure expected", 1, client.getTestStatsProvider().getCounter(nameBuilder + BookKeeperClientStats.FAILED_TLS_HANDSHAKE_COUNTER).get().longValue());
}

