@Test
public void testConcurrentExpandAndShrinkAndGet() throws Throwable {
    ConcurrentLongHashSet set = ConcurrentLongHashSet.newBuilder().expectedItems(2).concurrencyLevel(1).autoShrink(true).mapIdleFactor(0.25f).build();
    assertEquals(set.capacity(), 4);
    ExecutorService executor = Executors.newCachedThreadPool();
    final int readThreads = 16;
    final int writeThreads = 1;
    final int n = 1_000;
    CyclicBarrier barrier = new CyclicBarrier(writeThreads + readThreads);
    Future<?> future = null;
    AtomicReference<Exception> ex = new AtomicReference<>();
    for (int i = 0; i < readThreads; i++) {
        executor.submit(() -> {
            try {
                barrier.await();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            while (true) {
                try {
                    set.contains(1);
                } catch (Exception e) {
                    ex.set(e);
                }
            }
        });
    }
    assertTrue(set.add(1));
    future = executor.submit(() -> {
        try {
            barrier.await();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        for (int i = 0; i < n; i++) {
            // expand hashmap
            assertTrue(set.add(2));
            assertTrue(set.add(3));
            assertEquals(set.capacity(), 8);
            // shrink hashmap
            assertTrue(set.remove(2));
            assertTrue(set.remove(3));
            assertEquals(set.capacity(), 4);
        }
    });
    future.get();
    assertNull(ex.get());
    // shut down pool
    executor.shutdown();
}

