@Test
public void testConcurrentExpandAndShrinkAndGet() throws Throwable {
    ConcurrentOpenHashSet<String> set = ConcurrentOpenHashSet.<String>newBuilder().expectedItems(2).concurrencyLevel(1).autoShrink(true).mapIdleFactor(0.25f).build();
    assertEquals(set.capacity(), 4);
    ExecutorService executor = Executors.newCachedThreadPool();
    final int readThreads = 16;
    final int writeThreads = 1;
    final int n = 1_000;
    CyclicBarrier barrier = new CyclicBarrier(writeThreads + readThreads);
    Future<?> future = null;
    AtomicReference<Exception> ex = new AtomicReference<>();
    for (int i = 0; i < readThreads; i++) {
        executor.submit(() -> {
            try {
                barrier.await();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            while (true) {
                try {
                    set.contains("k2");
                } catch (Exception e) {
                    ex.set(e);
                }
            }
        });
    }
    assertTrue(set.add("k1"));
    future = executor.submit(() -> {
        try {
            barrier.await();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        for (int i = 0; i < n; i++) {
            // expand hashmap
            assertTrue(set.add("k2"));
            assertTrue(set.add("k3"));
            assertEquals(set.capacity(), 8);
            // shrink hashmap
            assertTrue(set.remove("k2"));
            assertTrue(set.remove("k3"));
            assertEquals(set.capacity(), 4);
        }
    });
    future.get();
    assertTrue(ex.get() == null);
    // shut down pool
    executor.shutdown();
}

