@Test
public void testPut() {
    ByteBuffer testBuffer;
    byte[] testBufferArray;
    Random rand = new Random();
    // Test1 - trying ZeroBuffer.put on small sized TestBuffer
    testBuffer = ByteBuffer.allocate(5);
    testBufferArray = testBuffer.array();
    testBufferArray[4] = 7;
    Assert.assertFalse("Test1 - It is supposed to contain non-zero byte", isFilledWithZeros(testBufferArray, 0, 5));
    ZeroBuffer.put(testBuffer);
    Assert.assertTrue("Test1 - After calling, ZeroBuffer.put There aren't supposed to be non-zero bytes", isFilledWithZeros(testBufferArray, 0, 5));
    // Test2 - trying ZeroBuffer.put on 64*1024 sized TestBuffer
    testBuffer = ByteBuffer.allocate(64 * 1024);
    testBufferArray = testBuffer.array();
    rand.nextBytes(testBufferArray);
    Assert.assertFalse("Test2 - It is supposed to contain random non-zero bytes", isFilledWithZeros(testBufferArray, 0, 64 * 1024));
    ZeroBuffer.put(testBuffer);
    Assert.assertTrue("Test2 - After calling, ZeroBuffer.put There aren't supposed to be non-zero bytes", isFilledWithZeros(testBufferArray, 0, 64 * 1024));
    // Test3 - trying ZeroBuffer.put on portion (64*1024) of large sized
    // TestBuffer (256*1024)
    testBuffer = ByteBuffer.allocate(256 * 1024);
    testBufferArray = testBuffer.array();
    rand.nextBytes(testBufferArray);
    Assert.assertFalse("Test3 - It is supposed to contain random non-zero bytes", isFilledWithZeros(testBufferArray, 64 * 1024, 64 * 1024));
    testBuffer.position(64 * 1024);
    ZeroBuffer.put(testBuffer, 64 * 1024);
    Assert.assertTrue("Test3 - After calling, ZeroBuffer.put There aren't supposed to be non-zero bytes " + "in the particular section", isFilledWithZeros(testBufferArray, 64 * 1024, 64 * 1024));
    Assert.assertFalse("Test3 - After calling, ZeroBuffer.put other sections shouldnt be touched", isFilledWithZeros(testBufferArray, 0, 64 * 1024));
    Assert.assertFalse("Test3 - After calling, ZeroBuffer.put other sections shouldnt be touched", isFilledWithZeros(testBufferArray, 128 * 1024, 128 * 1024));
}

@Test
public void testReadOnlyBuffer() {
    ByteBuffer testReadOnlyBuffer;
    byte[] testBufferArray;
    // Test1 - trying ZeroBuffer.readOnlyBuffer for small size
    testReadOnlyBuffer = ZeroBuffer.readOnlyBuffer(5);
