@Test
public void testExponentialBackoffWithDeadlineRetryPolicy() throws Exception {
    RetryPolicy policy = new ExponentialBackOffWithDeadlinePolicy(100, 55 * 1000, 20);
    // Retries are allowed as long as we don't exceed the limits of retry count and deadline
    assertTrue(policy.allowRetry(1, 5 * 1000));
    assertTrue(policy.allowRetry(4, 20 * 1000));
    assertTrue(policy.allowRetry(10, 50 * 1000));
    assertFalse(policy.allowRetry(0, 60 * 1000));
    assertFalse(policy.allowRetry(22, 20 * 1000));
    assertFalse(policy.allowRetry(22, 60 * 1000));
    // Verify that the wait times are in the range and with the excepted jitter, until deadline is exceeded
    assertTimeRange(policy.nextRetryWaitTime(0, 0), 0, 0);
    assertTimeRange(policy.nextRetryWaitTime(1, 0), 100, 110);
    assertTimeRange(policy.nextRetryWaitTime(1, 53 * 1000), 100, 110);
    assertTimeRange(policy.nextRetryWaitTime(2, 0), 200, 220);
    assertTimeRange(policy.nextRetryWaitTime(3, 0), 300, 330);
    assertTimeRange(policy.nextRetryWaitTime(3, 53 * 1000), 300, 330);
    assertTimeRange(policy.nextRetryWaitTime(4, 0), 500, 550);
    assertTimeRange(policy.nextRetryWaitTime(5, 0), 500, 550);
    // Verify that the final attempt is triggered at deadline.
    assertEquals(2000, policy.nextRetryWaitTime(10, 53 * 1000));
    assertEquals(4000, policy.nextRetryWaitTime(15, 51 * 1000));
}

@Test
public void testReconnectAfterExpired() throws Exception {
    final CountDownLatch expireLatch = new CountDownLatch(1);
    Watcher testWatcher = new Watcher() {

        @Override
        public void process(WatchedEvent event) {
            if (event.getType() == EventType.None && event.getState() == KeeperState.Expired) {
                expireLatch.countDown();
            }
        }
    };
    final int timeout = 2000;
    ZooKeeperWatcherBase watcherManager = new ZooKeeperWatcherBase(timeout, false).addChildWatcher(testWatcher);
    List<Watcher> watchers = new ArrayList<Watcher>(1);
    watchers.add(testWatcher);
    ZooKeeperClient client = new ShutdownZkServerClient(zkUtil.getZooKeeperConnectString(), timeout, watcherManager, ((retryPolicy instanceof BoundExponentialBackoffRetryPolicy) ? new BoundExponentialBackoffRetryPolicy(timeout, timeout, 0) : new ExponentialBackOffWithDeadlinePolicy(100, 20 * 1000, 0)));
    client.waitForConnection();
    Assert.assertTrue("Client failed to connect an alive ZooKeeper.", client.getState().isConnected());
    logger.info("Expire zookeeper client");
    expireZooKeeperSession(client, timeout);
    // wait until session expire
    Assert.assertTrue("Client registered watcher should receive expire event.", expireLatch.await(2 * timeout, TimeUnit.MILLISECONDS));
    Assert.assertFalse("Client doesn't receive expire event from ZooKeeper.", client.getState().isConnected());
    try {
        client.exists("/tmp", false);
        Assert.fail("Should fail due to connection loss.");
    } catch (KeeperException.ConnectionLossException cle) {
        // expected
    } catch (KeeperException.SessionExpiredException cle) {
        // expected
    }
    zkUtil.restartCluster();
    // wait for a reconnect cycle
    Thread.sleep(2 * timeout);
    Assert.assertTrue("Client failed to connect zookeeper even it was back.", client.getState().isConnected());
    try {
        client.exists("/tmp", false);
    } catch (KeeperException.ConnectionLossException cle) {
        Assert.fail("Should not throw ConnectionLossException");
    } catch (KeeperException.SessionExpiredException cle) {
        Assert.fail("Should not throw SessionExpiredException");
    }
}

