        // create keys with ttl
        long leaseId = FutureUtils.result(etcdClient.getLeaseClient().grant(1)).getID();
        CloseableClient ka = etcdClient.getLeaseClient().keepAlive(leaseId, Observers.observer(response -> {
        }));
