@Test
public void testTimer() {
    // load definitions for testing the timer
    // following 3 array lengths must match: each element defines values for one phase
    final int[] timeRange = new int[] { 90, 190, 50, 90, 100, 100 };
    final int[] timeBase = new int[] { 10, 10, 50, 10, 0, 0 };
    final int[] rate = new int[] { 1000, 1000, 1000, 1000, 0, 1 };
    // use a 5 second window for testing
    final int window = 5;
    FastTimer t = getMockedFastTimer(window, FastTimer.Buckets.fine);
    // fixed random seed for deterministic value distribution
    Random r = new Random(12345);
    int phase = 0;
    int sec = 0;
    long count = 0;
    // start generating test load for each of the configured phases
    while (phase < timeRange.length) {
        for (int i = 0; i < rate[phase]; i++) {
            t.update(r.nextInt(timeRange[phase]) + timeBase[phase], TimeUnit.MILLISECONDS);
            count++;
        }
        // advance mocked time to next second
        incSec();
        if (++sec % window == 0) {
            // every WINDOW seconds, check the timer values
            Snapshot s = t.getSnapshot();
            System.out.println(String.format("phase %3d: count=%10d, rate=%6.0f, min=%6.1f, avg=%6.1f, q99=%6.1f, max=%6.1f", phase, t.getCount(), t.getMeanRate(), ((double) s.getMin()) / 1000000.0, s.getMean() / 1000000.0, s.getValue(0.99) / 1000000.0, ((double) s.getMax()) / 1000000.0));
            // check count (events the timer has ever seen)
            assertEquals("FastTimer.getCount()", count, t.getCount());
            // check rate (should be precisely the configured rate)
            assertEquals("FastTimer.getMeanRate()", rate[phase], (int) Math.round(t.getMeanRate()));
            assertEquals("FastTimer.getOneMinuteRate()", rate[phase], (int) Math.round(t.getOneMinuteRate()));
            assertEquals("FastTimer.getFiveMinuteRate()", rate[phase], (int) Math.round(t.getFiveMinuteRate()));
            assertEquals("FastTimer.getFifteenMinuteRate()", rate[phase], (int) Math.round(t.getFifteenMinuteRate()));
            // at rates > 1000 (with fixed seed), we know that the following checks will be successful
            if (t.getMeanRate() >= 1000) {
                // check minimum value == lower bound
                assertEquals("FastSnapshot.getMin()", timeBase[phase], s.getMin() / 1000000);
                // check maximum value == upper bound
                assertEquals("FastSnapshot.getMax()", timeBase[phase] + timeRange[phase] - 1, (s.getMax() / 1000000));
                // check 99th percentile == upper bound
                assertEquals("FastSnapshot.getValue(0.99)", t.getBucketBound(t.getBucket(TimeUnit.MILLISECONDS.toNanos(timeBase[phase] + timeRange[phase] - 1))), (long) s.getValue(0.99));
                // check mean is within 10% of configured mean
                assertEquals("FastSnapshot.getMean()", (timeBase[phase] + (timeRange[phase] / 2)) / 10, (int) (Math.round(s.getMean() / 1000000) / 10));
            }
            // start next phase
            phase++;
        }
    }
}

