@Test
public void testJvmDirectMemoryMetrics() throws Exception {
    PropertiesConfiguration config = new PropertiesConfiguration();
    config.setProperty(PrometheusMetricsProvider.PROMETHEUS_STATS_HTTP_ENABLE, true);
    config.setProperty(PrometheusMetricsProvider.PROMETHEUS_STATS_HTTP_PORT, 0);
    config.setProperty(PrometheusMetricsProvider.PROMETHEUS_STATS_HTTP_ADDRESS, "127.0.0.1");
    PrometheusMetricsProvider provider = new PrometheusMetricsProvider();
    try {
        provider.start(config);
        assertNotNull(provider.server);
        ByteBuf byteBuf = ByteBufAllocator.DEFAULT.directBuffer(25);
        StringWriter writer = new StringWriter();
        provider.writeAllMetrics(writer);
        String s = writer.toString();
        // prometheus network string uses '\n' in all platform
        String[] split = s.split("\n");
        HashMap<String, String> map = new HashMap<>();
        for (String str : split) {
            String[] aux = str.split(" ");
            map.put(aux[0], aux[1]);
        }
        String directBytesMax = map.get("jvm_memory_direct_bytes_max{}");
        Assert.assertNotNull(directBytesMax);
        Assert.assertNotEquals("Nan", directBytesMax);
        Assert.assertNotEquals("-1", directBytesMax);
        String directBytesUsed = map.get("jvm_memory_direct_bytes_used{}");
        Assert.assertNotNull(directBytesUsed);
        Assert.assertNotEquals("Nan", directBytesUsed);
        Assert.assertTrue(Double.parseDouble(directBytesUsed) > 25);
        // ensure byteBuffer doesn't gc
        byteBuf.release();
    } finally {
        provider.stop();
    }
}

@Test
public void testNameResolver() throws Exception {
    int numServers = 3;
    Set<SocketAddress> addressSet = new HashSet<>();
    for (int i = 0; i < numServers; i++) {
        InetSocketAddress address = new InetSocketAddress("127.0.0.1", 3181 + i);
        addressSet.add(address);
        bookieDriver.createRegistrationManager().registerBookie(BookieId.parse("127.0.0.1:" + (3181 + i)), false, BookieServiceInfo.EMPTY);
    }
    LinkedBlockingQueue<List<EquivalentAddressGroup>> notifications = new LinkedBlockingQueue<>();
    @Cleanup("shutdown")
    NameResolver resolver = resolverProvider.newNameResolver(serviceUri, NameResolver.Args.newBuilder().setDefaultPort(0).setProxyDetector(GrpcUtil.DEFAULT_PROXY_DETECTOR).setSynchronizationContext(new SynchronizationContext((t, ex) -> {
    })).setServiceConfigParser(new NameResolver.ServiceConfigParser() {

        @Override
        public NameResolver.ConfigOrError parseServiceConfig(Map<String, ?> rawServiceConfig) {
            return null;
        }
    }).build());
    resolver.start(new Listener() {

        @Override
        public void onAddresses(List<EquivalentAddressGroup> servers, Attributes attributes) {
            notifications.add(servers);
        }

        @Override
        public void onError(Status error) {
        }
    });
    List<EquivalentAddressGroup> groups = notifications.take();
    assertEquals(numServers, groups.size());
    Set<SocketAddress> receivedSet = groups.stream().map(group -> group.getAddresses().get(0)).collect(Collectors.toSet());
    assertEquals(addressSet, receivedSet);
    // add 3 more servers
    for (int i = numServers; i < 2 * numServers; i++) {
        InetSocketAddress address = new InetSocketAddress("127.0.0.1", 3181 + i);
        addressSet.add(address);
        regManager.registerBookie(BookieId.parse("127.0.0.1:" + (3181 + i)), false, BookieServiceInfo.EMPTY);
    }
    List<EquivalentAddressGroup> notification = notifications.take();
    while (notification.size() < 2 * numServers) {
        notification = notifications.take();
    }
    assertEquals(2 * numServers, notification.size());
    receivedSet = notification.stream().map(group -> group.getAddresses().get(0)).collect(Collectors.toSet());
    assertEquals(addressSet, receivedSet);
}

