    DistributedLogConfiguration conf = new DistributedLogConfiguration().setEnsembleSize(5).setWriteQuorumSize(5).setAckQuorumSize(5).setLogSegmentRollingIntervalMinutes(0).setLogSegmentRollingConcurrency(-1).setMaxLogSegmentBytes(400000);
