public void testBasicIO() throws Exception {
    Path path = new Path("/path/to/" + runtime.getMethodName());
    assertFalse(fs.exists(path));
    try (FSDataOutputStream out = fs.create(path)) {
        for (int i = 0; i < 100; i++) {
