    store = new MVCCAsyncBytesStoreImpl(() -> new MVCCStoreImpl<>(), () -> namespace);
    spec = StateStoreSpec.builder().name(streamName).keyCoder(ByteArrayCoder.of()).valCoder(ByteArrayCoder.of()).stream(streamName).localStateStoreDir(testDir.newFolder()).build();
    result(store.init(spec));
    // verify the key/value pairs
    for (int i = 0; i < numKvs; i++) {
        byte[] value = result(store.get(getKey(i)));
        assertNotNull(value);
        assertArrayEquals(getValue(100 + i), value);
    }
}

