    long rangeId = streamId + 1;
    try (MVCCAsyncStore<byte[], byte[]> store = FutureUtils.result(factory.openStore(scId, streamId, rangeId, 0))) {
        log.info("Open store (scId = {}, streamId = {}, rangeId = {}) to test", scId, streamId, rangeId);
        String storeName = String.format("%s/%s/%s", normalizedName(scId), normalizedName(streamId), normalizedName(rangeId));
        assertEquals(storeName, store.name());
        File localStoreDir = Paths.get(storeDirs[(int) (streamId % storeDirs.length)].getAbsolutePath(), "ranges", normalizedName(scId), normalizedName(streamId), normalizedName(rangeId)).toFile();
        assertEquals(localStoreDir, store.spec().getLocalStateStoreDir());
        String streamName = MVCCStoreFactoryImpl.streamName(scId, streamId, rangeId);
        assertEquals(streamName, store.spec().getStream());
        assertTrue(store.spec().getKeyCoder() instanceof ByteArrayCoder);
        assertTrue(store.spec().getValCoder() instanceof ByteArrayCoder);
        assertSame(factory.writeIOScheduler().chooseThread(streamId), store.spec().getWriteIOScheduler());
        assertSame(factory.readIOScheduler().chooseThread(streamId), store.spec().getReadIOScheduler());
        assertSame(factory.checkpointScheduler().chooseThread(streamId), store.spec().getCheckpointIOScheduler());
        assertTrue(store.spec().getCheckpointStore() instanceof FSCheckpointManager);
        assertEquals(Duration.ofMinutes(15), store.spec().getCheckpointDuration());
    }
}

