@Test
public void test004_SearchReplaceBookieId() throws Exception {
    String zookeeper = BookKeeperClusterUtils.zookeeperConnectString(docker);
    String bookie = BookKeeperClusterUtils.getAnyBookie();
    int numEntries = 100;
    try (BookKeeper bk = new BookKeeper(zookeeper)) {
        long ledgerId;
        BookieId toReplace;
        BookieId replaceWith = BookieId.parse("192.0.2.1:3181");
        try (WriteHandle writelh = bk.newCreateLedgerOp().withDigestType(DigestType.CRC32C).withPassword(TestSmoke.PASSWD).withEnsembleSize(1).withWriteQuorumSize(1).withAckQuorumSize(1).execute().get()) {
            ledgerId = writelh.getId();
            toReplace = writelh.getLedgerMetadata().getAllEnsembles().get(0L).get(0);
            for (int i = 0; i < numEntries; i++) {
                writelh.append(("entry-" + i).getBytes());
            }
        }
        TestSmoke.readEntries(bk, ledgerId, numEntries);
        DockerUtils.runCommand(docker, bookie, bkctl, "bookieid", "searchreplace", "--from", toReplace.toString(), "--to", replaceWith.toString());
        try {
            TestSmoke.readEntries(bk, ledgerId, numEntries);
            fail("Shouldn't be able to read, as bookie id is rubbish");
        } catch (BKException.BKBookieHandleNotAvailableException e) {
            // expected
        }
        DockerUtils.runCommand(docker, bookie, bkctl, "bookieid", "searchreplace", "--from", replaceWith.toString(), "--to", toReplace.toString());
        TestSmoke.readEntries(bk, ledgerId, numEntries);
    }
}

