/**
 * A successful run with encoding multiple ledgers while generating cookie.
 */
@Test
public void testGenerateCookieWithMultipleLedgerIndexDirs() throws Exception {
    File cookieFile = testFolder.newFile("cookie-with-instance-id");
    String journalDir = "/path/to/journal";
    String ledgerDirs = "/path/to/ledgers,/path/to/more/ledgers";
    String indexDirs = "/path/to/indexes,/path/to/more/indexes";
    String instanceId = "test-instance-id";
    when(rm.getClusterInstanceId()).thenReturn(instanceId);
    assertTrue(getConsoleOutput(), runCommand(new String[] { "-l", ledgerDirs, "-ix", indexDirs, "-j", journalDir, "-o", cookieFile.getPath(), "-i", instanceId, BOOKIE_ID }));
    String consoleOutput = getConsoleOutput();
    assertTrue(consoleOutput, consoleOutput.contains("Successfully saved the generated cookie to " + cookieFile.getPath()));
    verify(rm, times(0)).getClusterInstanceId();
    List<String> cookieFields = Files.readAllLines(Paths.get(cookieFile.getPath()));
    for (String cookieField : cookieFields) {
        String[] fields = cookieField.split(" ");
        if (fields[0].equals("ledgerDirs:")) {
            assertEquals(fields[1], "\"" + encodeDirPaths(ledgerDirs.split(",")) + "\"");
        }
        if (fields[0].equals("indexDirs:")) {
            assertEquals(fields[1], "\"" + encodeDirPaths(indexDirs.split(",")) + "\"");
        }
    }
}

